internal object DuaAsDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("তোমাৰ দয়াৰ বাবে মই আশা কৰোঁ", "হে আল্লাহ, মই আশা কৰোঁ তোমাৰ দয়াৰ, গতিকে চকু ফুৰাৰ বাবেও মোক মোৰ ওপৰত এৰি নিদিবা, আৰু মোৰ সকলো কাম-কাজ ঠিক কৰি নিদিবা। তোমাৰ বাহিৰে কোনো ঈশ্বৰ নাই।", "দুৰ্ঘটনাত থকা ব্যক্তিৰ দুআ (দাৱাত আল-মাকৰুব)।", "নবী (ছাঃ)-এ ইয়াক সংকটত থকা ব্যক্তিৰ দুআ বুলি অভিহিত কৰিছিল।"),
        "dua_against_enemy_ahzab" to DuaText("শত্ৰুৰ সেনাৰ বিৰুদ্ধে", "হে আল্লাহ, কিতাপ প্ৰকাশ কৰোঁতা! খৰচ কৰাৰ ক্ষেত্ৰত দ্ৰুত! সংঘসমূহক পৰাস্ত কৰা। হে আল্লাহ, তেওঁলোকক পৰাস্ত কৰা আৰু জোকাৰি দিয়া।", "শত্ৰুৰ বিৰুদ্ধে-কনফেডাৰেটৰ যুদ্ধৰ ডুৱা।", "শত্ৰুৰ বিৰুদ্ধে নবী (ছাঃ)-ৰ প্ৰাৰ্থনা।"),
        "dua_anta_adudi" to DuaText("তুমি মোৰ সমৰ্থন।", "হে আল্লাহ, তুমি মোৰ সহায় আৰু সহায়কাৰী। তোমাৰ দ্বাৰা মই পৰিকল্পনা কৰোঁ, তোমাৰ দ্বাৰা মই আগবাঢ়ি যাম আৰু তোমাৰ দ্বাৰা মই যুদ্ধ কৰিম।", "প্ৰতিযোগিতা বা ডাঙৰ প্ৰত্যাহ্বানৰ আগতে।", "নৱদূত ছলীহ আলীহ ৱাছলে যুদ্ধত এই কথা কৈছিল।"),
        "dua_ikfinihim" to DuaText("তেওঁলোকৰ বিৰুদ্ধে মোক যথেষ্ট কৰক", "হে আল্লাহ, তুমি যি ইচ্ছা কৰা, তেওঁলোকৰ বিৰুদ্ধে মই যথেষ্ট।", "নিৰ্যাতনৰ দুষ্টতাৰ বিৰুদ্ধে-পিপল অৱ দ্য ডিচৰ কাহিনীত ল \"ৰাটোৰ দুৱা।", "আল্লাহে ল \"ৰাটো নিৰ্যাতনৰ পৰা ৰক্ষা কৰিছিল।"),
        "dua_qadarullah" to DuaText("যেতিয়া কিবা বেয়া হয়", "এয়া আল্লাহৰ আদেশ, আৰু তেওঁ যি ইচ্ছা কৰিছিল।", "যেতিয়া কিবা অপ্রীতিকৰ ঘটনা ঘটে, তেতিয়া'যদি কেৱল'বুলি কোৱাৰ পৰিৱৰ্তে।", "'যদি কেৱল'শায়তানৰ দুৱাৰ খোলে।"),
        "dua_ala_kulli_hal" to DuaText("প্ৰতিটো পৰিস্থিতিত প্ৰশংসা কৰক", "সকলো পৰিস্থিতিত সকলো প্ৰশংসা আল্লাহৰ বাবে।", "যেতিয়া কিবা অপছন্দৰ ঘটনা ঘটে।", "নবী (ছাঃ)-এ তেওঁৰ অপছন্দৰ কিবা এটাৰ সন্মুখীন হোৱাৰ সময়ত এই কথা কৈছিল।"),
        "dua_dogs_barking" to DuaText("নিশা কুকুৰে মাত শুনিবলৈ পায়", "মই শাপিত শয়তানৰ পৰা আল্লাহৰ আশ্ৰয় বিচাৰো।", "কুকুৰে ভুকি বা গাধাই ৰাতি ব্ৰে কৰাৰ শব্দ শুনিবলৈ পালে।", "আপুনি যি দেখা নাই তেওঁলোকে সেইটো দেখে।"),
        "dua_leaving_home_adilla" to DuaText("বিপথগামী হোৱাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত আশ্ৰয় বিচাৰোঁ যাতে মই বিপথগামী নহওঁ বা বিপথগামী হৈ পৰোঁ, যাতে মই পিছ পৰি যাওঁ বা পিছ পৰি যাওঁ, যাতে মই অন্যায় কৰোঁ বা অন্যায় কৰা নহয়, যাতে মই বোকাৰ দৰে আচৰণ নকৰোঁ বা বোকাৰ দৰে ব্যৱহাৰ কৰা হ'ব।", "ঘৰৰ পৰা ওলাই অহাৰ সময়ত-উম্ম ছালামাহ (আৰ. এ.)-ৰ দ্বাৰা বৰ্ণনা কৰা।", "নবী (ছাঃ)-এ যেতিয়াই তেওঁ নিজৰ ঘৰৰ পৰা ওলাই আহিছিল এই পাঠ কৰিছিল।"),
        "dua_ascending_descending" to DuaText("ওপৰলৈ যোৱা আৰু তললৈ অহা", "(ওপৰলৈ যোৱাৰ সময়ত) আল্লাহ সৰ্বশ্ৰেষ্ঠ।-(নামি অহাৰ সময়ত) আল্লাহৰ গৌৰৱ।", "যাত্ৰাৰ সময়ত ওপৰলৈ যোৱাৰ সময়ত'আল্লাহু আকবৰ \"আৰু নামি অহাৰ সময়ত'সুভানাল্লাহ\" কওক।", "ভ্ৰমণৰ সময়ত সঙ্গীসকলৰ (আৰ. এ.) অনুশীলন।"),
        "dua_traveller_sahar" to DuaText("ৰাতিপুৱা হোৱাৰ আগতে ভ্ৰমণকাৰীৰ দুৱা", "এজন শ্ৰোতাই আল্লাহৰ প্ৰশংসা আৰু তেওঁৰ ভাল অনুগ্ৰহ আমাৰ ওপৰত শুনিছে। হে আমাৰ প্ৰভু, আমাৰ লগত যাওক আৰু আমাক আপোনাৰ অনুগ্ৰহ দিয়ক-(মই এইটো কৈছোঁ) জাহান্নামৰ পৰা আল্লাহৰ ওচৰত আশ্ৰয় বিচাৰি।", "যাত্ৰাত, ৰাতিপুৱা হোৱাৰ আগতে।", "প্ৰবক্তা ছলীহুল্লাহ আলীহ ৱাছলে ভ্ৰমণৰ সময়ত ৰাতিপুৱা হোৱাৰ আগতে এই কথা কৈছিল।"),
        "dua_zawwadakallah" to DuaText("ভ্ৰমণকাৰীকঃ আল্লাহে তাকৱা প্ৰদান কৰক।", "আল্লাহে আপোনাক আপোনাৰ যাত্ৰাৰ বাবে তাকৱা প্ৰদান কৰক, আপোনাৰ পাপসমূহ ক্ষমা কৰক আৰু আপুনি য'তেই থাকক আপোনাৰ বাবে ভাল কৰক।", "যেতিয়া এজন ভ্ৰমণকাৰীক বিদায় জনোৱা হয়।", "নবী (ছাঃ)-এ এই দুআটো এজন যাত্ৰা কৰিবলৈ ওলাই অহা লোকক দিছিল।"),
        "dua_traveller_to_resident" to DuaText("পিছফালে থকা লোকসকলৰ বাবে ভ্ৰমণকাৰী", "মই আপোনাক আল্লাহৰ ওচৰত সমৰ্পিত কৰোঁ, যাৰ ওপৰত বিশ্বাস কেতিয়াও হেৰুৱা নহয়।", "পৰিয়ালক বিদায় জনোৱাৰ সময়ত যাত্ৰীয়ে কৈছিল।", "পৰিয়ালৰ সুৰক্ষাৰ দায়িত্ব আল্লাহৰ ওপৰত ন্যস্ত কৰা।"),
        "dua_entering_village" to DuaText("এখন চহৰ বা গাঁৱত প্ৰৱেশ কৰা", "হে সাত আকাশমণ্ডলৰ আৰু সেইবোৰৰ ছায়াৰ প্ৰভু, সাত পৃথিৱীৰ আৰু সেইবোৰে বহন কৰা সকলোৰে প্ৰভু, শয়তান আৰু তেওঁলোকে পথপ্ৰদৰ্শন কৰা সকলোৰে প্ৰভু, বতাহ আৰু সেইবোৰ বিক্ষিপ্ত হোৱা সকলোৰে প্ৰভু! আমি আপোনাক এই চহৰৰ ভাল আৰু ইয়াৰ লোকসকলৰ ভালৰ বাবে অনুৰোধ কৰোঁ, আৰু আমি ইয়াৰ বেয়া, ইয়াৰ লোকসকলৰ বেয়া আৰু ইয়াত থকা বেয়াৰ পৰা আপোনাৰ ওচৰত আশ্ৰয় বিচাৰোঁ।", "এখন চহৰ বা চহৰত প্ৰৱেশ কৰাৰ আগতে।", "নবী (ছাঃ)-এ যেতিয়াই এখন চহৰত প্ৰৱেশ কৰিব বিচাৰিছিল তেতিয়া এই পাঠ কৰিছিল।"),
        "dua_vehicle_stumbles" to DuaText("যেতিয়া বাহনখন খৰাং হয়", "আল্লাহৰ নামত।", "যেতিয়া মাউণ্ট বা বাহনখন পিছলি যায় বা হেৰুৱাই যায়,'শায়তন ধ্বংস হ'ব পাৰে'বুলি কোৱাৰ পৰিৱৰ্তে।", "বিসমিল্লাহ কোৱাৰ ফলত শয়তান মাখিৰ আকাৰলৈ সৰু হৈ পৰে।"),
        "dua_ajz_kasal_haram" to DuaText("দুৰ্বলতা আৰু বৃদ্ধ বয়সৰ পৰা অহা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত অসহায়তা আৰু অলসতাৰ পৰা, কাৰুদৰ আৰু বৃদ্ধ বয়সৰ পৰা, জীৱন আৰু মৃত্যুৰ পৰীক্ষাৰ পৰা, আৰু কবৰৰ শাস্তিৰ পৰা আশ্ৰয় বিচাৰো।", "আশ্ৰয়ৰ এক ব্যাপক দৈনিক দুআ।", "প্ৰায়ে নবীয়ে এটা দুআ কৰিছিল।"),
        "dua_sharri_ma_amiltu" to DuaText("মোৰ দুষ্ট কামৰ পৰা শৰণাধিকাৰী", "হে আল্লাহ, মই যি কৰিছোঁ তাৰ দুষ্টতা আৰু মই যি কৰা নাই তাৰ অশুভতাৰ পৰা মই তোমাৰ আশ্ৰয় বিচাৰো।", "আয়েশা (আৰ. এ.)-ৰ মতে, নবী (ছাঃ)-ৰ এটা দুআ।", "কি কৰা হৈছিল আৰু কি বাতিল কৰি ৰখা হৈছিল দুয়োটাৰ পৰিণামৰ পৰা সুৰক্ষা।"),
        "dua_jahdil_bala" to DuaText("গুৰুতৰ পৰীক্ষাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই কঠিন পৰীক্ষাৰ পৰা, দুখৰ পৰা, বেয়া আদেশৰ পৰা আৰু শত্ৰুৰ উল্লাসৰ পৰা আপোনাৰ আশ্ৰয় বিচাৰো।", "কঠোৰ পৰীক্ষা আৰু শত্ৰুৰ উল্লাসৰ পৰা শৰণাৰ্থী।", "নবী (ছাঃ)-এ এই চাৰিটা বস্তুৰ পৰা আশ্ৰয় বিচাৰিছিল।"),
        "dua_fitnat_ghina_faqr" to DuaText("ধন-সম্পত্তি আৰু দৰিদ্ৰতাৰ পৰীক্ষাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই আপোনাৰ ওচৰত অলসতা আৰু বৃদ্ধ বয়সৰ পৰা, পাপ আৰু ঋণৰ পৰা, কবৰৰ বিচাৰ আৰু শাস্তিৰ পৰা, জুইৰ বিচাৰ আৰু শাস্তিৰ পৰা, ধনৰ পৰীক্ষাৰ দুষ্টতাৰ পৰা, আৰু দৰিদ্ৰতাৰ পৰীক্ষাৰ পৰা আশ্ৰয় বিচাৰো।", "কবৰ, নৰক, সম্পদ আৰু দৰিদ্ৰতাৰ পৰীক্ষাৰ পৰা শৰণাৰ্থী (ডুৱাৰ অংশ)।", "নবী (ছাঃ)-ৰ পৰা এক ব্যাপক আশ্ৰয়ৰ দুআ।"),
        "dua_kufr_faqr" to DuaText("অবিশ্বাস আৰু দৰিদ্ৰতাৰ পৰা আশ্ৰয়", "হে আল্লাহ, মই অবিশ্বাস আৰু দৰিদ্ৰতাৰ পৰা তোমাৰ আশ্ৰয় বিচাৰো, আৰু কবৰৰ শাস্তিৰ পৰা তোমাৰ আশ্ৰয় বিচাৰো। তোমাৰ বাহিৰে কোনো উপাস্য নাই।", "তিনিবাৰ ৰাতিপুৱা আৰু সন্ধিয়া।", "আবু বক্ৰাহে (আৰ. এ.) নবী (ছাঃ)-ৰ এই কথা শুনিছিল।"),
        "dua_sharri_sami" to DuaText("মোৰ ইন্দ্রিয়ৰ দুষ্টতাৰ পৰা আশ্ৰয় লোৱা", "হে আল্লাহ, মই মোৰ শ্ৰৱণৰ দুষ্টতা, মোৰ দৃষ্টিৰ দুষ্টতা, মোৰ জিভাৰ দুষ্টতা, মোৰ হৃদয়ৰ দুষ্টতা আৰু মোৰ ইচ্ছাৰ দুষ্টতাৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰো।", "শাকাল ইবন হুমায়েদ (আৰ. এ.) ক শিকোৱা হৈছিল।", "হাত-ভৰি আৰু নিজকে পাপৰ পৰা ৰক্ষা কৰাৰ বাবে এটা ডুৱা।"),
        "dua_hadm_gharaq" to DuaText("আকস্মিক মৃত্যু আৰু দুৰ্ঘটনাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত আশ্ৰয় বিচাৰোঁ (এটা অট্টালিকাৰ দ্বাৰা), উচ্চতাৰ পৰা পৰি যোৱাৰ পৰা, ডুব যোৱাৰ পৰা, জ্বলোৱাৰ পৰা আৰু বৃদ্ধ বয়সৰ পৰা; মৃত্যুৰ সময়ত মোক পথভ্রষ্ট কৰা শায়তানৰ পৰা, তোমাৰ পথৰ পৰা পলায়ন কৰি মৃত্যুৰ পৰা, আৰু এটা (বিষাক্ত) দংশত মৃত্যুৰ পৰা।", "দুৰ্ঘটনা আৰু এক বেয়া মৃত্যুৰ পৰা আশ্ৰয়।", "নবী (ছাঃ)-ৰ পৰা এটা আশ্ৰয়ৰ দুৱা।"),
        "dua_ju_khiyanah" to DuaText("ভোক আৰু বিশ্বাসঘাতকতাৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত ভোকৰ পৰা আশ্ৰয় বিচাৰোঁ, কিয়নো ই এজন দুষ্ট সঙ্গী, আৰু মই বিশ্বাসঘাতকতাৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰোঁ, কিয়নো ই এজন দুষ্ট বিশ্বাসী।", "ভোক আৰু বিশ্বাসঘাতকতাৰ পৰা শৰণাৰ্থী।", "নবী (ছাঃ)-ৰ পৰা এটা আশ্ৰয়ৰ দুৱা।"),
        "dua_huda_tuqa" to DuaText("নিৰ্দেশনা, ধৰ্মনিষ্ঠা, সতীত্ব আৰু পৰ্যাপ্ততা", "হে আল্লাহ, মই তোমাৰ পৰামৰ্শ, ধৰ্মনিষ্ঠা, সতীত্ব আৰু আত্মনিৰ্ভৰশীলতাৰ বাবে অনুৰোধ কৰোঁ।", "নবী (ছাঃ)-ৰ এটা সংক্ষিপ্ত, বিস্তৃত দুআ।", "ধৰ্ম আৰু এই পৃথিৱীৰ চাৰিটা মৌলিক আশীৰ্বাদ।"),
        "dua_aslih_li_dini" to DuaText("মোৰ ধৰ্ম, পৃথিৱী আৰু পৰৱৰ্তী সময় সংশোধন কৰক", "হে আল্লাহ, মোৰ ধৰ্ম সঠিক কৰা, যি মোৰ সকলো কাম-কাজৰ সুৰক্ষা; মোৰ পার্থিব জীৱন সঠিক কৰা, য'ত মোৰ জীৱিকা আছে; আৰু মোৰ পৰৱৰ্তী জীৱন সঠিক কৰা, য'লৈ মই ঘূৰি যাম। মোৰ বাবে জীৱন প্ৰতিটো ভালৰ ক্ষেত্ৰত বৃদ্ধি কৰা, আৰু মৃত্যুক মোৰ বাবে প্ৰতিটো বেয়াৰ পৰা আৰাম দিয়া।", "ধৰ্ম, এই পৃথিৱী আৰু পৰৱৰ্তী পৰিৱেশ-এই তিনিওটা সংস্কৰণ।", "নবী (ছাঃ)-ৰ এক বিস্তৃত দ্বৈত।"),
        "dua_musarrifal_qulub" to DuaText("আমাৰ হৃদয় আপোনাৰ আজ্ঞাপালনৰ ফালে ঘূৰাই দিয়ক", "হে আল্লাহ, হৃদয়ৰ পৰিৱৰ্তনকাৰী, আমাৰ হৃদয় আপোনাৰ আজ্ঞাপালনৰ ফালে ঘূৰাই দিয়ক।", "হৃদয়ক আজ্ঞাবহতাত দৃঢ় ৰাখিবলৈ এটা দুআ।", "সকলো মানুহৰ হৃদয় অতি দয়ালুৰ দুটা আঙুলিৰ মাজত থাকে।"),
        "dua_jannah_nar" to DuaText("জাহ্নাৰ বাবে বিচাৰি থকা, জুইৰ পৰা শৰণাৰ্থী", "হে আল্লাহ, মই তোমাৰ ওচৰত জৰুৰী স্বৰ্গ বিচাৰো আৰু অগ্নিৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰো।", "তাছাহুদৰ পিছত বা যিকোনো সময়তে।", "নবী (ছাঃ)-এ কৈছিলঃ আমাৰ দুআও ইয়াৰ চাৰিওফালে ঘূৰি আছে।"),
        "dua_khayri_kullih" to DuaText("সকলো ভাল, এতিয়া আৰু পিছত", "হে আল্লাহ, মই তোমাৰ ওচৰত সকলো ভাল-তাৎক্ষণিক আৰু বিলম্বিত, মই যি জানো আৰু মই নাজানো-আৰু মই সকলো বেয়া-তাৎক্ষণিক আৰু বিলম্বিত, মই যি জানো আৰু যি নাজানো তাৰ পৰা তোমাৰ ওচৰত আশ্ৰয় বিচাৰোঁ। হে আল্লাহ, মই তোমাক জৰ্গমণ্ডল বিচাৰোঁ আৰু যি শব্দ আৰু কাৰ্য্যই মোক ইয়াৰ ওচৰলৈ লৈ আহে, আৰু মই তোমাৰ ওচৰত অগ্নিৰ পৰা আশ্ৰয় বিচাৰোঁ আৰু যি শব্দ আৰু কাৰ্য্যই মোক ইয়াৰ ওচৰলৈ লৈ আহে তাৰ পৰা।", "নবী (ছাঃ)-এ আয়েশাক (আৰ. এ.) এই ব্যাপক দুআ শিকোৱা হৈছিল।", "এটা ডুৱা যিয়ে প্ৰতিটো ভালখিনি সংগ্ৰহ কৰে।"),
        "dua_ihdini_saddidni" to DuaText("মোক পথ দেখুৱাওক আৰু মোক সঠিকভাৱে ৰাখক", "হে আল্লাহ, মোক পথ দেখুৱাওক আৰু মোক সঠিক পথত লৈ যাওক।", "নবী (ছাঃ)-এ আলী (ছাঃ)-ক এই বিষয়ে শিকাইছিল।", "পথ নিৰ্দেশনাক পথ নিৰ্দেশনা হিচাপে আৰু সদাদক তীৰৰৰৰ পোনতা হিচাপে ভাবক।"),
        "dua_hubbaka" to DuaText("আল্লাহৰ প্ৰেম বিচাৰি", "হে আল্লাহ, মই তোমাৰ প্ৰেম, তোমাক ভাল পোৱাসকলৰ প্ৰেম, আৰু মোক তোমাৰ প্ৰেমলৈ অনা কাৰ্য্যসমূহ বিচাৰো। হে আল্লাহ, তোমাৰ প্ৰেম মোৰ বাবে, মোৰ পৰিয়ালৰ বাবে আৰু ঠাণ্ডা পানীৰ বাবে বেছি মৰমৰ কৰা।", "নবী ছলীহ আলীহ ৱাছলামৰ দ্বাৰা সম্পৰ্কিত দাউদ (আৰু আৰু আৰু) ৰ দুআ।", "আল্লাহৰ প্ৰেম হৈছে আটাইতকৈ ডাঙৰ সম্পদ।"),
        "dua_filal_khayrat" to DuaText("ভাল কৰা আৰু বেয়া কৰা এৰি দিয়া", "হে আল্লাহ, মই তোমাক অনুৰোধ কৰোঁ যে তুমি মোক ভাল কাম কৰিবলৈ, বেয়া কাম এৰি যাবলৈ আৰু দৰিদ্ৰসকলক ভাল পোৱাৰ বাবে সক্ষম কৰা, আৰু তুমি মোক ক্ষমা কৰা আৰু মোৰ ওপৰত দয়া কৰা। আৰু যেতিয়া তুমি এটা জাতিৰ বাবে পৰীক্ষা কৰাৰ ইচ্ছা কৰা, মোক পৰীক্ষা নকৰাকৈ লৈ যাবা। মই তোমাৰ প্ৰেম, তোমাক ভাল পোৱাসকলৰ প্ৰেম, আৰু মোক তোমাৰ প্ৰেমৰ ওচৰলৈ অনা কাৰ্য্যৰ প্ৰেমৰ বাবে তোমাক বিচাৰোঁ।", "আল্লাহে নৱগত সল্লল্লাহু অলৈহি ঵সল্লমক সপোনত এই দুআ শিকোৱাইছিল।", "নবী (ছাঃ)-এ কৈছিলঃ এইটো সঁচা, গতিকে ইয়াক শিকা আৰু শিকোৱা।"),
        "dua_bi_ilmikal_ghayb" to DuaText("জীৱন ভাল হৈ থকাৰ সময়তে মোক জীয়াই থাকিবলৈ দিয়ক।", "হে আল্লাহ, তোমাৰ অদৃশ্যৰ জ্ঞান আৰু সৃষ্টিৰ ওপৰত তোমাৰ ক্ষমতাৰ দ্বাৰা-যেতিয়ালৈকে তুমি জানানে যে মোৰ বাবে জীৱন ভাল, আৰু মোক লৈ যাবা যেতিয়া তুমি জানিলা যে মোৰ বাবে মৃত্যু ভাল। হে আল্লাহ, মই তোমাক ব্যক্তিগত আৰু ৰাজহুৱাভাৱে ভয় কৰিবলৈ অনুৰোধ কৰোঁ, সন্তুষ্টি আৰু ক্ৰোধত সত্যৰ বাক্যৰ বাবে, আৰু দৰিদ্ৰতা আৰু ধন-সম্পত্তিৰ মাজত সংযমৰ বাবে।", "আম্মাৰ ইবন য়াসিৰ (আৰ. এ.) (আৰ. এ.) ৰ প্ৰাৰ্থনা দুআ (আৰ. এ.)।", "নবী (ছাঃ)-এ প্ৰাৰ্থনাৰ জৰিয়তে এই দুআ কৰিছিল।"),
        "dua_ism_azam_mannan" to DuaText("ইছম-ই-আজমঃ আল-মান্নান", "হে আল্লাহ, মই তোমাক অনুৰোধ কৰোঁ, কিয়নো সকলো প্রশংসা তোমাৰ। তুমি ছাড়া কোনো উপাস্য নাই, অনুগ্রহদাতা, আকাশমণ্ডলী আৰু পৃথিৱীৰ প্ৰতিষ্ঠাপক। হে মহানতা আৰু সন্মানৰ গৰাকী, হে সৰ্বজীৱী, হে পালনকাৰী!", "নবী ছলীহ আলীহ ৱাছলে কৈছিল যে এই ব্যক্তিয়ে আল্লাহৰ সৰ্বশ্ৰেষ্ঠ নামেৰে দুআ সৃষ্টি কৰিছিল।", "এই নামেৰে তৈয়াৰ কৰা এটা দুৱাৰ উত্তৰ দিয়া হয়।"),
        "dua_ism_azam_ahad_samad" to DuaText("ইছম-ই-আজমঃ আল-আহাদ আছ-ছামাদ", "হে আল্লাহ, মই তোমাক প্ৰাৰ্থনা কৰোঁ, কিয়নো মই সাক্ষ্য দিছোঁ যে তুমি আল্লাহ; তোমাৰ বাহিৰে কোনো ঈশ্বৰ নাই, এজন, আত্মনিৰ্ভৰশীল, যি জন্ম নেনেই হয়, আৰু তেওঁৰ সৈতে কোনো তুলনীয় নাই।", "নবী ছলীহ আলীহ ৱাছলে কৈছিল যে এই ব্যক্তিয়ে আল্লাহৰ মহানতম নামৰে প্ৰশ্ন কৰিছিল।", "যেতিয়া ইয়াৰ দ্বাৰা সোধা হয়, তেওঁ দিয়ে; যেতিয়া ইয়াৰ দ্বাৰা কোৱা হয়, তেওঁ উত্তৰ দিয়ে।"),
        "dua_thabbitni_hadiyan" to DuaText("মোক দৃঢ়, পথপ্ৰদৰ্শক আৰু পথ প্ৰদৰ্শক কৰি তোলক", "হে আল্লাহ, মোক দৃঢ় কৰি তোলক, আৰু মোক পথ প্ৰদৰ্শন কৰা আৰু পথ প্ৰদৰ্শন কৰা মানুহ কৰা।", "নবী (ছাঃ)-এ জাৰিৰ (ৰা.) (নিজৰ বাবে'থাবিতনী') ৰ বাবে এই দুআটো কৰিছিল।", "জাৰিৰ (আৰ. এ.) ৰ মূল ডুৱাত'থাবিত-হু'শব্দটো ব্যৱহাৰ কৰা হৈছে।"),
        "dua_rabbighfir_tub_alayya" to DuaText("মোক ক্ষমা কৰক আৰু মোৰ অনুতাপ গ্ৰহণ কৰক", "হে মোৰ প্ৰভু, মোক ক্ষমা কৰা আৰু মোৰ অনুতাপ গ্ৰহণ কৰা। নিশ্চয় তুমি অনুতাপৰ প্ৰতিপালক, দৰকাৰী।", "এটা বৈঠকতে এশবাৰ-নবী (ছাঃ)-ৰ অনুশীলন।", "সাহাবীসকলে নবী (ছাঃ)-ক এটা বৈঠকতে এশবাৰকৈ কোৱা বুলি গণনা কৰিছিল।"),
        "dua_rafiq_ala" to DuaText("মৃত্যু হোৱা ব্যক্তিৰ দুৱা", "হে আল্লাহ, মোক ক্ষমা কৰা, মোৰ ওপৰত দয়া কৰা আৰু সৰ্বোচ্চ সংগীৰ সৈতে মোৰ সৈতে যোগ দিয়া।", "নবী (ছাঃ)-ৰ অন্তিম দুআ-অসুস্থ ব্যক্তিয়ে নিজৰ বাবে ক'বলৈ।", "তেওঁৰ মৃত্যুৰ সময়ত নবী (ছাঃ)-এ এই দুআ কৰিছিল।"),
        "dua_la_bas_tahur" to DuaText("ৰোগীক সান্ত্বনা দিয়াঃ শুদ্ধকৰণ", "কোনো ক্ষতি নাই; যদি আল্লাহৰ ইচ্ছা হয়, ই হৈছে শুদ্ধকৰণ (পাপৰ পৰা)।", "ভ্ৰমণ কৰাৰ সময়ত ৰোগীক সান্ত্বনা দিবলৈ।", "ৰোগীসকলক সাক্ষাৎ কৰাৰ সময়ত নবী (ছাঃ)-এ এই কথা কৈছিল।"),
        "dua_talqeen" to DuaText("তালকিন ফৰ দ্য ডাইয়িং", "আল্লাহৰ বাহিৰে আন কাৰো উপাসনা কৰাৰ অধিকাৰ নাই।", "এজন মৃত ব্যক্তিৰ ওচৰত কলিমা পাঠ কৰক (তেওঁলোকক এইটো ক'বলৈ বাধ্য নকৰিব)।", "যিজনৰ শেষ শব্দ'লা ইলাহা ইল্লাল্লাহ'তেওঁ স্বৰ্গত প্ৰৱেশ কৰিব (আবু দাউদ 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("মৃত্যু কামনা কৰাৰ পৰিৱৰ্তে", "হে আল্লাহ, মোক জীয়াই ৰাখক যেতিয়ালৈকে মোৰ বাবে জীৱন ভাল, আৰু মৃত্যু মোৰ বাবে ভাল হ'লে মোক লৈ যাওক।", "কষ্টত মৃত্যু কামনা কৰাৰ পৰিৱৰ্তে।", "নবী (ছাঃ)-এ মৃত্যু কামনা কৰাত নিষেধাজ্ঞা আৰোপ কৰিছিল আৰু ইয়াৰ পৰিৱৰ্তে এই শিক্ষা দিছিল।"),
        "dua_for_one_i_cursed" to DuaText("কাৰোবাৰ বাবে মই শব্দৰ দ্বাৰা আঘাত কৰোঁ", "হে আল্লাহ, মই যি বিশ্বাসীক অপমান কৰিছোঁ, কিয়ামতৰ দিনা তাক তোমাৰ ওচৰৰ এক উপায় কৰি তোলক।", "আপুনি খংত বেয়া কথা কোৱা কাৰোবাৰ বাবে।", "নবী (ছাঃ)-ৰ এটা দুআ।"),
    )
}
